canActivate(context: ExecutionContext): boolean {
  // BUG: only reads the handler, never the controller class
  const required = this.reflector.get<Role[]>(ROLES_KEY, context.getHandler());
  if (!required) return true; // a route with only a CONTROLLER-level @Roles() falls through here -> open!
  const { user } = context.switchToHttp().getRequest();
  return required.some((role) => user?.roles?.includes(role));
}

model.en:
canActivate(context: ExecutionContext): boolean {
  const required = this.reflector.getAllAndOverride<Role[]>(ROLES_KEY, [
    context.getHandler(), // handler-level @Roles() wins
    context.getClass(),   // controller default applies when the handler has none
  ]);
  if (!required) return true; // genuinely no @Roles() anywhere -> open
  const { user } = context.switchToHttp().getRequest();
  const ok = required.some((role) => user?.roles?.includes(role));
  if (!ok) throw new ForbiddenException();
  return ok;
}

Why: reflector.get(handler) only inspects the handler, so a controller-wide @Roles('admin') is invisible and every handler without its own decorator falls into the 'return true' open path. getAllAndOverride scans [getHandler(), getClass()] and returns the first defined value — the handler overrides, the controller is the fallback. Throwing ForbiddenException instead of returning false yields a clean, message-bearing 403.

model.ru:
canActivate(context: ExecutionContext): boolean {
  const required = this.reflector.getAllAndOverride<Role[]>(ROLES_KEY, [
    context.getHandler(), // @Roles() уровня хендлера побеждает
    context.getClass(),   // дефолт контроллера применяется, когда у хендлера его нет
  ]);
  if (!required) return true; // действительно нет @Roles() нигде -> открыт
  const { user } = context.switchToHttp().getRequest();
  const ok = required.some((role) => user?.roles?.includes(role));
  if (!ok) throw new ForbiddenException();
  return ok;
}

Почему: reflector.get(handler) осматривает только хендлер, поэтому @Roles('admin') на уровне контроллера невидим, и каждый хендлер без своего декоратора падает в открытый путь 'return true'. getAllAndOverride сканирует [getHandler(), getClass()] и возвращает первое определённое значение — хендлер перекрывает, контроллер — фолбэк. Выброс ForbiddenException вместо возврата false даёт чистый 403 с сообщением.
